insert into public.settings (key, value) values
  ('base', $conteudo$[{"name":"Outubro","m":9,"y":2026,"headline":"O plantio está acontecendo, e a gente mostra de perto.","start":19,"summary":"Calendário a partir de 19/10. Mês de máxima presença no campo: plantio da soja, entregas no pico, testes e vistorias. O conteúdo prova, com bastidores e dados, o cuidado de especialista por trás de cada saco de semente.","themes":["Rodada técnica com Rogério Coimbra: qualidade de sementes","Evolução do plantio da soja","Avaliações de stand e visitas de pós-venda","Testes pré-plantio realizados nas fazendas","Pico das entregas de sementes de soja","Evolução das vendas de algodão","Produção de sementes: plantio","Emergência: vistoria de campo"],"posts":[{"d":19,"fmt":"Reels","p":"tecnico","theme":"Rodada técnica: qualidade de sementes","short":"Rodada técnica: como foi","st":["Repost do Reels com o sticker \"Novo post\", marcando Rogério Coimbra e as fazendas.","Duas ou três fotos do evento, uma por story, sem texto ou com uma frase curta."],"title":"Rodada técnica com Rogério Coimbra: como foi nas fazendas","how":"Reels de 20 a 30s montado só com o material que já temos: fotos do evento animadas com zoom lento (efeito Ken Burns), intercaladas com os takes curtos de 2 a 4s. Ordem sugerida: chegada à fazenda, Rogério em campo explicando, produtores ouvindo e perguntando, foto do grupo. Se algum take tiver fala boa, usar como abertura com legenda na tela. Trilha instrumental e texto final: \"Conhecimento compartilhado também é semente.\" Escolher as fotos com melhor luz e fazer um ajuste de cor igual em todas.","caption":"Na última semana, levamos a conversa sobre qualidade de sementes para dentro das fazendas.\n\nNa rodada técnica com Rogério Coimbra, produtores e consultores discutiram, no campo, o que faz uma semente entregar todo o potencial da genética: germinação, vigor, sanidade e cuidado em cada etapa.\n\nObrigado a cada fazenda que abriu a porteira e a todos que participaram. Conhecimento compartilhado também é semente.","tags":"#FranciosiSementes #ConstruindoLegado #QualidadeDeSementes #RodadaTécnica #Soja"},{"d":21,"fmt":"Carrossel","p":"tecnico","theme":"Rodada técnica: qualidade de sementes","short":"Aprendizados da rodada","st":["Repost do carrossel com o sticker \"Novo post\".","Um take curto de Rogério Coimbra (até 15s), com legenda na tela."],"title":"Qualidade de sementes: o que ficou da rodada técnica","how":"Carrossel de 6 telas usando as fotos do evento como fundo, com uma faixa de texto sobreposta para garantir leitura. Capa: a melhor foto de Rogério em campo e o título. Telas 2 a 5: um aprendizado por tela (germinação, vigor, sanidade, armazenamento ou testes pré-plantio), em até 2 linhas. Tela 6: foto do grupo e convite para falar com o time técnico. Validar os textos com Rogério antes de publicar. Não precisa gravar nada novo.","caption":"Semente boa não é sorte. É processo.\n\nReunimos os principais aprendizados da rodada técnica com Rogério Coimbra nas fazendas: o que avaliar, por que cada teste importa e como a qualidade da semente aparece no stand e na produtividade.\n\nArraste, salve e compartilhe com quem está no campo com você.","tags":"#FranciosiSementes #ConstruindoLegado #QualidadeDeSementes #Soja #Agronomia"},{"d":23,"fmt":"Carrossel","p":"tecnico","theme":"Emergência: vistoria de campo","short":"Vistoria de emergência","title":"Vistoria de emergência: o que observamos no campo","how":"Fotos reais da vistoria: plântulas emergindo, uniformidade entre linhas, possíveis falhas. Uma observação técnica por tela (\"O que olhamos\" + \"Por que importa\"). Tom didático, sem jargão.","caption":"A emergência é o primeiro retrato da safra.\n\nNas vistorias de campo, observamos uniformidade, vigor das plântulas e falhas na linha. Essas informações ajudam o produtor a agir cedo e proteger o potencial produtivo.\n\nArraste e veja o que nosso time avalia em cada visita.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #Emergência #VistoriaDeCampo"},{"d":26,"fmt":"Reels","p":"pessoas","theme":"Visitas de pós-venda","short":"Pós-venda no campo","title":"Pós-venda: você fala, a gente escuta","how":"Gravar uma visita real de pós-venda: consultor e produtor caminhando na lavoura, conversa espontânea. Trecho de depoimento do produtor (10 a 15s) sobre o acompanhamento. Pedir autorização de uso de imagem.","caption":"Nossa relação não termina quando a semente é entregue.\n\nNas visitas de pós-venda, a gente acompanha a emergência, avalia o stand e escuta o produtor de perto. Porque parceria de verdade se constrói safra após safra.\n\nVocê fala, a gente escuta.","tags":"#FranciosiSementes #ConstruindoLegado #PósVenda #Parceria #Soja"},{"d":28,"fmt":"Reels","p":"pessoas","theme":"Pico das entregas de sementes de soja","short":"Bastidores da expedição","title":"Quem está por trás de cada entrega","how":"Mini-perfis de 3 colaboradores da expedição/logística (5 a 8s cada): nome, função, uma frase sobre o trabalho. Encerrar com o time reunido. Gravar com celular estabilizado, ambiente real.","caption":"Por trás de cada entrega, tem gente que veste a camisa.\n\nNessa reta de plantio, nosso time de expedição e logística trabalha para que a semente chegue no tempo certo da sua lavoura.\n\nObrigado, time. Vocês são parte do legado que a gente constrói.","tags":"#FranciosiSementes #ConstruindoLegado #Pessoas #Logística #Soja"},{"d":30,"fmt":"Carrossel","p":"comercial","theme":"Evolução das vendas de algodão","short":"Algodão: portfólio","title":"Algodão: a cultivar certa para o seu sistema","how":"Carrossel com 1 cultivar de algodão por tela (nome em caixa alta, 3 atributos-chave, região indicada). Capa com foto de capulho aberto. Última tela: \"Fale com nosso consultor e planeje sua safra de algodão.\" Use dados reais do portfólio.","caption":"A safra de algodão se planeja agora.\n\nConheça as cultivares do nosso portfólio e encontre a genética que combina com a sua área, seu manejo e seu objetivo de produtividade.\n\nNosso time comercial está pronto para te ajudar a escolher. Chama no direct ou fale com o consultor da sua região.","tags":"#FranciosiSementes #ConstruindoLegado #Algodão #Cultivares #Safra2627"}]},{"name":"Novembro","m":10,"y":2026,"headline":"Plantio encerrado, lavoura crescendo, algodão e forrageiras em pauta.","summary":"A soja sai do plantio e entra no desenvolvimento; as entregas se concluem. O foco comercial migra para o algodão (pico de vendas) e começa a abrir espaço para as forrageiras.","themes":["Finalização do plantio da soja","Conclusão das entregas de sementes de soja","Pico das vendas de algodão","Desenvolvimento das lavouras de soja","Evolução das vendas de forrageiras"],"posts":[{"d":4,"fmt":"Reels","p":"campo","theme":"Finalização do plantio da soja","short":"Reta final do plantio","title":"Reta final do plantio da soja","how":"Imagens de drone das últimas áreas sendo plantadas, intercaladas com lavouras já emergidas (contraste entre fases). Texto na tela: \"Últimos hectares. Primeiras folhas.\" 20s.","caption":"Últimos hectares sendo plantados. Primeiras folhas aparecendo.\n\nA reta final do plantio da soja mostra o resultado de semanas de trabalho intenso, e o começo de uma nova fase da safra.\n\nSeguimos juntos no campo.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #Plantio #Safra2627"},{"d":6,"fmt":"Carrossel","p":"comercial","theme":"Pico das vendas de algodão","short":"Como escolher a cultivar","title":"4 critérios para escolher a cultivar de algodão","how":"Carrossel educativo-comercial: ciclo, tolerância a doenças, adaptação à região, potencial de fibra. Uma tela por critério com explicação de 2 linhas. Última tela apresenta o portfólio e o CTA do consultor.","caption":"Escolher a cultivar de algodão certa é uma decisão que define a safra.\n\nCiclo, sanidade, adaptação regional e qualidade de fibra: arraste e veja o que considerar antes de decidir.\n\nQuer ajuda para comparar opções? Nosso time técnico-comercial está à disposição.","tags":"#FranciosiSementes #ConstruindoLegado #Algodão #Cultivares #Agronomia"},{"d":9,"fmt":"Carrossel","p":"tecnico","theme":"Desenvolvimento das lavouras de soja","short":"Estádios da soja","title":"Estádios vegetativos da soja: o que acontece em cada fase","how":"Ilustração/foto de planta por estádio (VE, VC, V1, V2…Vn), com o que observar em cada um. Usar fotos reais de lavoura da região. Visual técnico, fundo claro, legendas em azul.","caption":"Sua soja já emergiu? Então é hora de acompanhar cada estádio.\n\nConhecer as fases vegetativas ajuda a planejar o manejo no momento certo e proteger o potencial da genética que você escolheu.\n\nSalve para consultar na lavoura.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #ManejoDaSoja #Agronomia"},{"d":11,"fmt":"Reels","p":"pessoas","theme":"Conclusão das entregas de sementes de soja","short":"Entregas concluídas","title":"Missão cumprida: entregas de soja concluídas","how":"Último caminhão saindo, time reunido no armazém, depoimento curto do gerente de logística. Encerrar com número total da safra (cargas ou clientes atendidos), se puder ser divulgado.","caption":"Última carga entregue. Missão cumprida.\n\nEncerramos as entregas de sementes de soja desta safra com o compromisso de sempre: a semente certa, no tempo certo, para quem constrói um legado no campo.\n\nObrigado a cada cliente pela confiança e ao nosso time pela dedicação.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #Logística #Parceria"},{"d":13,"fmt":"Carrossel","p":"comercial","theme":"Evolução das vendas de forrageiras","short":"Portfólio forrageiras","title":"Conheça nossas forrageiras","how":"Apresentação do portfólio de forrageiras: uma espécie/cultivar por tela, com indicação de uso (pastejo, palhada, integração). Fotos de pastagem formada. CTA para consultor ou revenda.","caption":"Pastagem forte começa com semente de qualidade.\n\nConheça as forrageiras do nosso portfólio e descubra a opção ideal para formação de pastagem, palhada ou integração lavoura-pecuária.\n\nFale com a gente e encontre a revenda mais próxima.","tags":"#FranciosiSementes #ConstruindoLegado #Forrageiras #Pastagem #Pecuária"},{"d":16,"fmt":"Reels","p":"pessoas","theme":"Pico das vendas de algodão","short":"Depoimento algodão","title":"Quem planta, conta: produtor de algodão","how":"Depoimento de um cliente de algodão na propriedade (30 a 45s): por que escolheu a Franciosi, como foi o acompanhamento, resultados. Planos abertos da lavoura + close nas mãos e no capulho.","caption":"Nada fala mais alto que o resultado no campo.\n\nNeste vídeo, [nome do produtor], de [cidade], conta como a parceria com a Franciosi faz parte da história da sua produção de algodão.\n\nSoluções efetivas. Resultados reais. Legado de impacto.","tags":"#FranciosiSementes #ConstruindoLegado #Algodão #Depoimento #Parceria"},{"d":18,"fmt":"Carrossel","p":"tecnico","theme":"Desenvolvimento das lavouras de soja","short":"30 primeiros dias","title":"5 pontos de atenção nos primeiros 30 dias da soja","how":"Lista técnica: stand, plantas daninhas, pragas iniciais, nutrição, umidade do solo. Ícones da marca como marcadores decorativos. Linguagem descomplicada.","caption":"Os primeiros 30 dias definem muito do que vem depois.\n\nArraste e confira os 5 pontos que merecem sua atenção no início do desenvolvimento da soja.\n\nPrecisa de apoio técnico? Nosso time está no campo com você.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #ManejoDaSoja #Produtividade"},{"d":20,"fmt":"Carrossel","p":"tecnico","theme":"Evolução das vendas de forrageiras","short":"Forrageiras + ILP","title":"Forrageiras na integração lavoura-pecuária","how":"Carrossel explicando benefícios: palhada, ciclagem de nutrientes, renda na entressafra. Usar um diagrama simples de ciclo (soja → forrageira → gado). Dados de fonte confiável (Embrapa) citados.","caption":"Mais palhada, solo mais protegido e renda na entressafra.\n\nAs forrageiras são peças-chave na integração lavoura-pecuária. Arraste e entenda como elas ajudam a construir um sistema mais produtivo e sustentável.","tags":"#FranciosiSementes #ConstruindoLegado #ILP #Forrageiras #SoloVivo"},{"d":23,"fmt":"Reels","p":"campo","theme":"Desenvolvimento das lavouras de soja","short":"Consultor no campo","title":"Um dia com o consultor no campo","how":"Formato \"um dia com\": acompanhar um consultor da Franciosi em visitas, com legendas de horário (7h, 10h, 15h). Mostrar avaliação de lavoura, conversa com produtor, anotações. 45 a 60s.","caption":"Como é um dia de quem acompanha a sua lavoura de perto?\n\nAcompanhamos [nome], consultor técnico da Franciosi, em um dia de visitas às lavouras de soja em desenvolvimento.\n\nCuidado de especialista, do plantio à colheita.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #Consultoria #Agro"},{"d":25,"fmt":"Post estático","p":"comercial","theme":"Pico das vendas de algodão","short":"Últimas semanas","title":"Algodão: últimas semanas para garantir sua semente","how":"Peça comercial direta: foto de lavoura de algodão, título forte, CTA para o consultor. Urgência sem agressividade, tom de alerta amigável.","caption":"O plantio do algodão está chegando, e a sua semente, já está garantida?\n\nAinda dá tempo de escolher a cultivar ideal e contar com nosso acompanhamento técnico. Fale com o consultor da sua região.\n\nLink na bio.","tags":"#FranciosiSementes #ConstruindoLegado #Algodão #Sementes #Safra2627"},{"d":27,"fmt":"Reels","p":"comercial","theme":"Evolução das vendas de forrageiras","short":"Forrageiras na revenda","title":"Onde encontrar as forrageiras Franciosi","how":"Gravação em revenda parceira: embalagem na prateleira, vendedor indicando o produto, cliente levando. Texto na tela com regiões/revendas. Marcar as revendas parceiras.","caption":"As forrageiras Franciosi estão chegando às revendas parceiras.\n\nProcure na loja agropecuária da sua cidade e garanta semente de qualidade para formar ou reformar sua pastagem.\n\nMarque aqui a revenda onde você compra.","tags":"#FranciosiSementes #ConstruindoLegado #Forrageiras #Revenda #Pecuária"},{"d":30,"fmt":"Carrossel","p":"legado","theme":"Desenvolvimento das lavouras de soja","short":"Balanço do mês","title":"Novembro no campo: o que construímos juntos","how":"Retrospectiva do mês em 5 telas: plantio concluído, entregas finalizadas, lavouras em desenvolvimento, novidades em algodão e forrageiras. Fotos reais do mês, uma frase por tela.","caption":"Um mês de muito trabalho e de muita parceria.\n\nPlantio concluído, entregas finalizadas e lavouras se desenvolvendo bem. Arraste e reviva com a gente os momentos de novembro no campo.\n\nQue venha dezembro.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #Algodão #Forrageiras"}]},{"name":"Dezembro","m":11,"y":2026,"headline":"Algodão no solo, forrageiras na revenda, soja ganhando força.","summary":"O algodão de sequeiro entra no solo, as forrageiras chegam ao pico no varejo e a soja recém-implantada se desenvolve. Fechamento do ano com gratidão e legado.","themes":["Plantio do algodão de sequeiro e avaliações de stand","Pico das vendas de forrageiras no varejo","Desenvolvimento da soja recém-implantada"],"posts":[{"d":2,"fmt":"Reels","p":"campo","theme":"Plantio do algodão de sequeiro","short":"Plantio do algodão","title":"Começa o plantio do algodão de sequeiro","how":"Mesma linguagem do Reels de abertura da soja (continuidade visual): plantadeira, semente de algodão na mão, solo. Texto: \"Agora é a vez do algodão.\" 20 a 30s.","caption":"Agora é a vez do algodão.\n\nCom o plantio do algodão de sequeiro, começa mais uma etapa importante da safra, e a gente segue no campo, acompanhando cada área de perto.\n\nBoa safra a todos os produtores de algodão.","tags":"#FranciosiSementes #ConstruindoLegado #Algodão #Plantio #Safra2627"},{"d":4,"fmt":"Carrossel","p":"tecnico","theme":"Pico das vendas de forrageiras no varejo","short":"Guia de forrageiras","title":"Qual forrageira escolher? Guia por objetivo","how":"Carrossel em formato de guia: \"Quero pastejo intensivo → X\", \"Quero palhada → Y\", \"Quero ILP → Z\". Uma tela por objetivo, linguagem simples. Última tela com CTA para revenda.","caption":"Cada objetivo pede uma forrageira diferente.\n\nArraste e descubra qual opção do nosso portfólio combina melhor com o seu sistema: pastejo, palhada ou integração.\n\nSalve e leve para a revenda.","tags":"#FranciosiSementes #ConstruindoLegado #Forrageiras #Pastagem #Pecuária"},{"d":5,"fmt":"Post estático","p":"data","date":true,"theme":"Dia Mundial do Solo","short":"Dia Mundial do Solo","title":"Dia Mundial do Solo","how":"Close de solo vivo com palhada e uma plântula de soja emergindo. Texto: \"Solo forte, legado forte.\" Tons terrosos da paleta secundária (marrom, areia).","caption":"Tudo o que a gente constrói no campo começa embaixo dos nossos pés.\n\nNo Dia Mundial do Solo, celebramos quem cuida da terra com responsabilidade, porque solo saudável é a base de toda safra e de todo legado.","tags":"#FranciosiSementes #ConstruindoLegado #DiaMundialDoSolo #SoloVivo #Agro"},{"d":7,"fmt":"Carrossel","p":"tecnico","theme":"Desenvolvimento da soja recém-implantada","short":"Soja: o que observar","title":"Soja recém-implantada: o que observar agora","how":"Fotos reais da lavoura com setas/círculos indicando pontos de atenção (folhas, pragas iniciais, uniformidade). Uma observação por tela. Fechar com convite para falar com o time técnico.","caption":"Sua soja está ganhando força, e esse é o momento de olhar com atenção.\n\nArraste e veja os sinais que merecem acompanhamento nesta fase do desenvolvimento.\n\nDúvidas? Fale com o consultor Franciosi da sua região.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #ManejoDaSoja #Agronomia"},{"d":9,"fmt":"Reels","p":"tecnico","theme":"Avaliações de stand no algodão","short":"Stand do algodão","title":"Avaliação de stand no algodão","how":"Consultor em lavoura de algodão recém-emergido, explicando a contagem de plantas e a importância da uniformidade. Formato tutorial, direto para a câmera, 30 a 45s.","caption":"No algodão, a uniformidade do stand faz toda a diferença.\n\nNosso consultor mostra como avaliar a população de plantas logo após a emergência e o que fazer com essa informação.\n\nSalve para a sua próxima vistoria.","tags":"#FranciosiSementes #ConstruindoLegado #Algodão #Stand #Agronomia"},{"d":11,"fmt":"Post estático","p":"comercial","theme":"Pico das vendas de forrageiras no varejo","short":"Procure na revenda","title":"Forrageiras Franciosi: procure na sua revenda","how":"Foto de produto (embalagem) em destaque sobre fundo de pastagem. Título curto, CTA \"Procure na revenda mais próxima\". Marcar revendas parceiras nos stories do mesmo dia.","caption":"Época de formar pastagem é agora.\n\nAs forrageiras Franciosi estão disponíveis nas revendas parceiras. Qualidade de semente de quem é especialista há quase 40 anos.\n\nProcure na revenda mais próxima de você.","tags":"#FranciosiSementes #ConstruindoLegado #Forrageiras #Pastagem #Revenda"},{"d":14,"fmt":"Reels","p":"campo","theme":"Desenvolvimento da soja recém-implantada","short":"Soja vista do alto","title":"A soja vista do alto","how":"Imagens de drone de lavouras de clientes (com autorização), mostrando o fechamento das entrelinhas. Comparativo \"outubro x dezembro\" da mesma área, se houver. Trilha instrumental, 15 a 20s.","caption":"Do plantio até aqui: olha como a lavoura cresceu.\n\nAs imagens mostram o desenvolvimento da soja em áreas de clientes da região. Genética forte, manejo bem-feito e muito trabalho.\n\nResultado que se vê de longe.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #Drone #Safra2627"},{"d":16,"fmt":"Carrossel","p":"pessoas","theme":"Encerramento do ano","short":"Time da safra","title":"As pessoas que fizeram esta safra acontecer","how":"Retratos de colaboradores de diferentes áreas (campo, UBS, logística, comercial, escritório), com nome e uma frase curta. Fotos com luz natural, fundo de campo ou armazém.","caption":"Uma safra se faz com sementes, e com pessoas.\n\nConheça alguns dos rostos que trabalharam para que cada semente chegasse ao campo com a qualidade Franciosi.\n\nObrigado, time. O legado é nosso.","tags":"#FranciosiSementes #ConstruindoLegado #Pessoas #NossoTime #Agro"},{"d":18,"fmt":"Reels","p":"pessoas","theme":"Pico das vendas de forrageiras no varejo","short":"Depoimento pecuarista","title":"Quem planta, conta: pecuarista","how":"Depoimento de pecuarista cliente na pastagem formada (30 a 45s): resultado da forrageira, lotação, qualidade do pasto. Imagens do gado pastejando.","caption":"Pasto bom é sinônimo de rebanho bem nutrido.\n\n[Nome do pecuarista], de [cidade], conta como as forrageiras Franciosi fazem parte do sistema de produção da fazenda.\n\nSoluções efetivas. Resultados reais.","tags":"#FranciosiSementes #ConstruindoLegado #Forrageiras #Pecuária #Depoimento"},{"d":21,"fmt":"Carrossel","p":"legado","theme":"Encerramento do ano","short":"Retrospectiva 2026","title":"Retrospectiva 2026: um ano de campo","how":"Carrossel de 8 a 10 telas com os momentos-chave do ano (lançamentos, eventos, safra, pessoas). Uma foto forte por tela + legenda curta. Última tela: \"Obrigado por construir esse legado com a gente.\"","caption":"2026 foi um ano de campo, de parceria e de muitas sementes plantadas, dentro e fora da lavoura.\n\nArraste e reviva com a gente alguns dos momentos que marcaram o nosso ano.\n\nObrigado por construir esse legado com a gente.","tags":"#FranciosiSementes #ConstruindoLegado #Retrospectiva2026 #Agro"},{"d":23,"fmt":"Carrossel","p":"tecnico","theme":"Pico das vendas de forrageiras no varejo","short":"Semeadura de forrageiras","title":"Semeadura de forrageiras: 4 cuidados essenciais","how":"Dicas práticas: preparo do solo, taxa de semeadura, profundidade, umidade. Uma por tela, com foto de campo. Linguagem simples e direta para o pecuarista.","caption":"Vai semear sua pastagem? Então não deixe esses cuidados de lado.\n\nArraste e confira 4 pontos que fazem diferença no estabelecimento das forrageiras.\n\nSalve e compartilhe com quem está formando pasto.","tags":"#FranciosiSementes #ConstruindoLegado #Forrageiras #Pastagem #Pecuária"},{"d":25,"fmt":"Post estático","p":"data","date":true,"theme":"Natal","short":"Natal","title":"Feliz Natal","how":"Imagem calma e afetiva: família no campo ou mesa no fim de tarde na fazenda. Texto curto com a assinatura da marca. Evitar clichês natalinos genéricos (renas, neve).","caption":"Que o Natal seja tempo de colher o que realmente importa: família, saúde e boas parcerias.\n\nA Franciosi Sementes deseja a você e aos seus um Feliz Natal.","tags":"#FranciosiSementes #ConstruindoLegado #FelizNatal"},{"d":28,"fmt":"Reels","p":"campo","theme":"Desenvolvimento da soja recém-implantada","short":"Soja em desenvolvimento","title":"Como está a soja na última semana do ano","how":"Consultor em campo fazendo um \"boletim\" de 30s: estádio atual, condições, o que vem pela frente em janeiro. Formato informativo, direto para a câmera.","caption":"Última semana do ano e a lavoura segue firme.\n\nNosso consultor traz um rápido boletim de como está a soja na região e o que o produtor deve acompanhar nas próximas semanas.\n\nSeguimos com você em 2027.","tags":"#FranciosiSementes #ConstruindoLegado #Soja #BoletimDeCampo #Agro"},{"d":31,"fmt":"Post estático","p":"data","date":true,"theme":"Ano Novo","short":"Ano Novo","title":"Feliz 2027","how":"Foto de amanhecer sobre a lavoura. Texto: \"Um novo ciclo para plantar.\" Assinatura da marca com o símbolo em destaque.","caption":"Todo novo ano é uma nova safra de oportunidades.\n\nQue 2027 seja de boas colheitas, parcerias fortes e muitos legados construídos no campo.\n\nFeliz Ano Novo!","tags":"#FranciosiSementes #ConstruindoLegado #FelizAnoNovo #Agro"}]}]$conteudo$::jsonb),
